/**
 * Navigation for a CATALOGUE build: departments → spine families → leaves,
 * generated by `scripts/capture_catalogue_shelves.py` as `demo/navigation.json`
 * and compiled in as `__CATALOGUE_NAVIGATION__` (vite.config.ts, and
 * scripts/postbuild.mjs for the prerender; reader: scripts/catalogue-navigation.mjs).
 *
 * The constant is null for the MVP build (the default), whose navigation stays
 * the static engine shelf list in liveSpineShelves.ts. It is set only when the
 * dataset's navigation.json was written for the same capture as its
 * manifest.json, so the menus can never describe a different dataset than the
 * pages they link to.
 *
 * ⛔ Every slug in here is a redesign-SPINE slug, and in a catalogue build
 * `/shelf/:slug` means a spine slug. The spine's slugs collide with the legacy
 * /browse categories (`mobile-phones` is both), so nothing here builds a
 * /browse link from a spine slug or the reverse.
 */
export interface CatalogueNavNode {
  slug: string;
  name: string;
  /** Families placed at this node itself (a department or family can hold some). */
  n_clusters: number;
  /** Families anywhere in the subtree: what the node's /shelf page lists. */
  n_clusters_subtree: number;
  n_stores: number;
}

export interface CatalogueNavFamily extends CatalogueNavNode {
  leaves: CatalogueNavNode[];
}

export interface CatalogueNavDepartment extends CatalogueNavNode {
  families: CatalogueNavFamily[];
}

export interface CatalogueNavigation {
  version: number;
  source_collection: string;
  captured_at: string;
  n_families: number;
  departments: CatalogueNavDepartment[];
}

declare const __CATALOGUE_NAVIGATION__: CatalogueNavigation | null | undefined;

/** null outside a catalogue build, and wherever the define is absent (node tests, the Pages Function). */
export const CATALOGUE_NAVIGATION: CatalogueNavigation | null =
  typeof __CATALOGUE_NAVIGATION__ === 'undefined' ? null : __CATALOGUE_NAVIGATION__ ?? null;

/** A link in a family's shelf list (the same shape as liveSpineShelves' LiveSpineShelf). */
export interface CatalogueShelfLink {
  slug: string;
  label: string;
  count: number;
}

/**
 * A family's shelf links: its leaves, plus the family's own page ("All …")
 * when families are placed at the family itself or it has no leaves — so no
 * family's products are reachable only by a heading link.
 */
export function familyShelfLinks(family: CatalogueNavFamily): CatalogueShelfLink[] {
  const leaves = family.leaves.map((leaf) => ({ slug: leaf.slug, label: leaf.name, count: leaf.n_clusters_subtree }));
  if (family.n_clusters > 0 || leaves.length === 0) {
    leaves.push({ slug: family.slug, label: `All ${family.name}`, count: family.n_clusters_subtree });
  }
  return leaves;
}
